function person_table(array $headers,array $rows):void{echo '<div class="table-wrap"><table><thead><tr>';foreach($headers as $h)echo '<th>'.e($h).'</th>';echo '</tr></thead><tbody>';foreach($rows as $row){echo '<tr>';foreach($row as $cell)echo '<td>'.$cell.'</td>';echo '</tr>';}if(!$rows)echo '<tr><td colspan="'.count($headers).'">Sin registros.</td></tr>';echo '</tbody></table></div>';}
