 if($q!==''){$where.=" AND (CONCAT(u.first_name,' ',u.last_name) LIKE ? OR u.email LIKE ? OR u.phone LIKE ?)";$params=array_fill(0,3,'%'.$q.'%');}
 if($view==='collaborators'){
