  if(preg_match('/^[a-z0-9:_-]{1,100}$/',$workCity)){$where.=" AND EXISTS(SELECT 1 FROM partner_profiles pfilter WHERE pfilter.user_id=u.id AND JSON_SEARCH(pfilter.profile_json,'one',?,NULL,'$.onboarding.workCities[*].id') IS NOT NULL)";$params[]=$workCity;}
  if(in_array($review,['draft','submitted','approved','rejected','suspended'],true)){$where.=' AND EXISTS(SELECT 1 FROM partner_profiles pfilter WHERE pfilter.user_id=u.id AND pfilter.status=?)';$params[]=$review;}
 }
 $s=db()->prepare('SELECT COUNT(*) FROM users u WHERE '.$where);$s->execute($params);$total=(int)$s->fetchColumn();$owner=$view==='customers'?'customer_user_id':'partner_user_id';
 $s=db()->prepare("SELECT u.id,u.first_name,u.last_name,u.email,u.phone,u.created_at,p.status partner_status,COALESCE(r.total,0) reservations,COALESCE(r.accepted,0) accepted,COALESCE(r.completed,0) completed FROM users u LEFT JOIN partner_profiles p ON p.user_id=u.id LEFT JOIN (SELECT `$owner` user_id,COUNT(*) total,SUM(status='accepted') accepted,SUM(status='completed') completed FROM reservations GROUP BY `$owner`) r ON r.user_id=u.id WHERE $where ORDER BY u.created_at DESC,u.id LIMIT 25 OFFSET $offset");$s->execute($params);$rows=$s->fetchAll();$controls=[];
 if($rows){$ids=array_column($rows,'id');$marks=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT a.entity_id,a.details_json FROM audit_log a JOIN (SELECT entity_id,MAX(id) latest FROM audit_log WHERE action='user.account_control_changed' AND entity_type='user' AND entity_id IN ($marks) GROUP BY entity_id) latest_control ON a.id=latest_control.latest");$s->execute($ids);foreach($s->fetchAll() as $control)$controls[$control['entity_id']]=json_decode($control['details_json'],true);}
 ?><section class="panel"><div class="panel-head"><h3><?=$total?> <?=$view==='collaborators'?'colaboradores':'clientes'?></h3><form method="get" class="directory-search"><input type="hidden" name="view" value="<?=e($view)?>"><input name="q" value="<?=e($q)?>" placeholder="Nombre, correo o teléfono" aria-label="Buscar persona"><?php if($view==='collaborators'):?><input name="activity" value="<?=e($activity??'')?>" placeholder="Actividad: driver, guide…"><input name="city" value="<?=e($workCity??'')?>" placeholder="Código de ciudad"><select name="review"><option value="">Todos los estados</option><?php foreach(partner_labels() as $key=>$label):?><option value="<?=e($key)?>" <?=($review??'')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select><a href="?view=collaborators&amp;registration=settings">Requisitos y comisiones</a><?php endif;?><button class="btn secondary">Buscar</button></form></div><?php
 $cells=[];foreach($rows as $row){$status=$controls[$row['id']]['status']??'active';$cells[]=[e(trim($row['first_name'].' '.$row['last_name'])).'<small>Alta '.e($row['created_at']).'</small>',e($row['email']??'—').'<small>'.e($row['phone']??'—').'</small>','<span class="badge '.e($status).'">'.e(account_labels()[$status]??$status).'</span>'.($view==='collaborators'?'<small>'.e(partner_labels()[$row['partner_status']??'draft']).'</small>':''),(int)$row['reservations'].' solicitudes<small>'.(int)$row['accepted'].' confirmados · '.(int)$row['completed'].' realizados</small>','<a class="btn secondary" href="?view='.e($view).'&id='.e(rawurlencode($row['id'])).'">Ver ficha</a>'];}
 person_table(['Nombre','Contacto','Cuenta / registro','Servicios','Ficha'],$cells);
 echo '<nav class="directory-pagination">';if($page>1)echo '<a href="?'.e(http_build_query(['view'=>$view,'q'=>$q,'page'=>$page-1])).'">← Anterior</a>';echo '<span>Página '.$page.'</span>';if($offset+25<$total)echo '<a href="?'.e(http_build_query(['view'=>$view,'q'=>$q,'page'=>$page+1])).'">Siguiente →</a>';echo '</nav></section>';page_footer();exit;
