$s=db()->prepare('SELECT entry_type,amount_minor,currency,status,description,created_at FROM wallet_ledger WHERE user_id=? AND wallet_type=? ORDER BY created_at DESC,id DESC LIMIT 50');$s->execute([$uid,$walletType]);$moves=$s->fetchAll();
